 public partial class VeilGame {
  Texture2D sanctuaryMap,cityGradient;Font citySerif;
  readonly int[] cityMapButtonIds=new int[6];
  string cityBuilding="mine";int cityResourcePage,cityDetailTab;bool sanctuaryWorkshopOpen;
  readonly Color cityRed=new Color(.63f,.115f,.075f),citySilver=new Color(.43f,.43f,.38f),cityIvory=new Color(.92f,.875f,.77f);
  readonly string[] CityMapBuildings={"timber","mine","blacksmith","quarry","weaver","hunters"};
  readonly Vector2[] CityBuildingPoints={new Vector2(.27f,.38f),new Vector2(.28f,.75f),new Vector2(.19f,.52f),new Vector2(.81f,.76f),new Vector2(.86f,.58f),new Vector2(.83f,.36f)};
  readonly Vector2[] CityLabelPoints={new Vector2(.27f,.455f),new Vector2(.28f,.825f),new Vector2(.19f,.605f),new Vector2(.81f,.84f),new Vector2(.86f,.655f),new Vector2(.83f,.435f)};
  Rect CityMapRect=>new Rect(24,190,1036,672);
  Rect CityPanelRect=>new Rect(1076,190,500,672);
  void InitCityArt(){if(!sanctuaryMap)sanctuaryMap=Resources.Load<Texture2D>("Sanctuary/SanctuaryMap");if(!citySerif)citySerif=Font.CreateDynamicFontFromOSFont("Georgia",22);if(!cityGradient){cityGradient=new Texture2D(2,64,TextureFormat.RGBA32,false){name="Smooth iron shading",wrapMode=TextureWrapMode.Clamp};for(int y=0;y<64;y++)for(int x=0;x<2;x++)cityGradient.SetPixel(x,y,Color.Lerp(new Color(.035f,.041f,.043f),new Color(.085f,.092f,.091f),y/63f));cityGradient.Apply();}}
  GUIStyle CityType(int size,Color color,bool heading=false,TextAnchor align=TextAnchor.UpperLeft){var style=CardStyle(size,color,align,heading);if(heading&&citySerif)style.font=citySerif;return style;}
  void CityFrame(Rect r,bool active=false){InitCityArt();Box(new Rect(r.x+3,r.y+4,r.width,r.height),new Color(0,0,0,.55f));GUI.DrawTexture(r,cityGradient);Box(new Rect(r.x+6,r.y+6,r.width-12,r.height-12),new Color(.018f,.022f,.023f,.65f));CardOutline(r,new Color(.31f,.27f,.22f));CardOutline(new Rect(r.x+2,r.y+2,r.width-4,r.height-4),new Color(.075f,.08f,.075f));CardOutline(new Rect(r.x+5,r.y+5,r.width-10,r.height-10),active?cityRed:new Color(.19f,.19f,.17f));float cut=9;foreach(float sx in new[]{r.x+2,r.xMax-12})foreach(float sy in new[]{r.y+2,r.yMax-12}){HudLine(new Vector2(sx,sy+cut),new Vector2(sx+cut,sy),active?cityRed:citySilver,1);}}
  void CityButton(float x,float y,float w,float h,string title,Action action,bool enabled=true,bool active=false){InitCityArt();Rect r=new Rect(x,y,w,h);int index=buttons.Count;if(enabled)buttons.Add(action);bool focused=enabled&&selection==index;GUI.DrawTexture(r,cityGradient);if(active)Box(new Rect(x+2,y+2,w-4,h-4),new Color(.27f,.044f,.027f,.82f));CardOutline(r,active?cityRed:focused?cityIvory:new Color(.30f,.29f,.25f));CardOutline(new Rect(x+3,y+3,w-6,h-6),new Color(.13f,.12f,.10f));HudLine(new Vector2(x+5,y+1),new Vector2(x+w-5,y+1),focused?cityIvory:new Color(.41f,.37f,.29f));GUI.Label(r,title,CityType(h<32?12:h<42?15:18,enabled?cityIvory:muted,false,TextAnchor.MiddleCenter));if(enabled&&Event.current.type==EventType.MouseDown&&Event.current.button==0&&r.Contains(Event.current.mousePosition)){selection=index;action();Event.current.Use();}}
  string CityBuildingName(string id){int i=Array.IndexOf(Settlement.Buildings,id);return i<0?"Sanctuary":Settlement.BuildingNames[i];}
  int CitySource(string id)=>id=="mine"?0:id=="hunters"?1:id=="weaver"?2:-1;
  bool CityBuildingMax(string id){int n=city.BuildingLevel(id);return id=="mine"&&n>=7||(id=="weaver"||id=="hunters")&&n>=5||id=="blacksmith"&&n>=9||(id=="tailor"||id=="leatherworker")&&n>=2;}
  void SelectCityBuilding(string id){if(Array.IndexOf(Settlement.Buildings,id)<0)return;cityBuilding=id;cityResourcePage=cityDetailTab=0;sanctuaryWorkshopOpen=false;industryPage=0;int source=CitySource(id);if(source>=0)industrySource=source;selection=Array.IndexOf(CityMapBuildings,id)>=0?4+Array.IndexOf(CityMapBuildings,id):0;}
  void OpenCityWorkshop(bool armourPage,int material=3){sanctuaryWorkshopOpen=true;industryPage=1;smithArmourPage=armourPage;gearMaterial=material;selection=0;}
  bool ReadCityController(){if(state!=ScreenState.Settlement||tab!=2||gearBagOpen||resourceFocus)return false;var pad=PreferredPad;if(pad==null)return false;if(sanctuaryWorkshopOpen){if(pad.buttonEast.wasPressedThisFrame){sanctuaryWorkshopOpen=false;selection=0;return true;}return false;}int direction=pad.rightShoulder.wasPressedThisFrame?1:pad.leftShoulder.wasPressedThisFrame?-1:0;if(direction==0)return false;int index=Array.IndexOf(CityMapBuildings,cityBuilding);SelectCityBuilding(CityMapBuildings[(Math.Max(0,index)+direction+6)%6]);gamepadCombat=true;return true;}
  void IndustryScreen(){InitCityArt();if(sanctuaryWorkshopOpen){LegacyIndustryScreen();CityButton(48,840,325,35,"Return to city",()=>{sanctuaryWorkshopOpen=false;selection=0;});return;}SanctuaryCityScreen();}
  void CityNavigation(){string[] titles={"Expedition","Loadout","Settlement"};for(int i=0;i<3;i++){int page=i;CityButton(24+i*382,127,370,46,titles[i],()=>{tab=page;sanctuaryWorkshopOpen=false;industryPage=0;selection=0;},true,i==2);}CityButton(1180,127,396,46,"Settings",OpenSettings);}
  void SanctuaryCityScreen(){city.EnsureGear();city.EnsureIndustry();InitCityArt();Box(new Rect(0,0,1600,900),new Color(.014f,.018f,.020f));CityNavigation();Rect r=CityMapRect;CityFrame(r);if(sanctuaryMap)GUI.DrawTexture(new Rect(r.x+7,r.y+7,r.width-14,r.height-14),sanctuaryMap,ScaleMode.StretchToFill);else GUI.Label(r,"Settlement map could not load.",CityType(22,cityIvory));
   for(int i=0;i<CityMapBuildings.Length;i++)DrawCityBuilding(i);
   CityDetails();GUI.Label(new Rect(26,871,1040,22),gamepadCombat?"LB / RB  Buildings     D-pad  Focus controls     A  Select     Y  Resources":"Select a building to manage it.   ·   Settlement production continues during expeditions.",CityType(12,muted));GUI.Label(new Rect(1088,871,480,22),"1 real minute = 1 city hour  ·  Fractional stock saved",CityType(11,muted,false,TextAnchor.UpperRight));
  }
  Rect CityBuildingHit(int index){Rect r=CityMapRect;Vector2 p=CityBuildingPoints[index];return new Rect(r.x+(p.x-.085f)*r.width,r.y+(p.y-.075f)*r.height,r.width*.17f,r.height*.17f);}
  Rect CityBuildingLabel(int index){Rect r=CityMapRect;Vector2 p=CityLabelPoints[index];float w=CityMapBuildings[index]=="hunters"?170:CityMapBuildings[index]=="weaver"?166:150;return new Rect(r.x+p.x*r.width-w/2,r.y+p.y*r.height,w,31);}
  void DrawCityBuilding(int index){string id=CityMapBuildings[index];Rect hit=CityBuildingHit(index),label=CityBuildingLabel(index);int button=buttons.Count;cityMapButtonIds[index]=button;buttons.Add(()=>SelectCityBuilding(id));bool chosen=cityBuilding==id,focus=selection==button,hover=hit.Contains(Event.current.mousePosition)||label.Contains(Event.current.mousePosition);CityFrame(label,chosen||focus);GUI.Label(label,CityBuildingName(id),CityType(14,cityIvory,true,TextAnchor.MiddleCenter));if(chosen){Vector2 p=new Vector2(label.x-20,label.center.y);Box(new Rect(p.x-12,p.y-12,24,24),new Color(.15f,.025f,.018f));HudDiamond(p,17,cityRed);HudDiamond(p,13,cityIvory);GUI.Label(new Rect(p.x-10,p.y-10,20,20),"+",CityType(16,cityIvory,false,TextAnchor.MiddleCenter));}if(hover||focus){GUI.Label(new Rect(label.x,label.yMax+2,label.width,21),"Level "+city.BuildingLevel(id),CityType(12,cityIvory,false,TextAnchor.MiddleCenter));}if(hover&&Event.current.type==EventType.MouseDown&&Event.current.button==0){SelectCityBuilding(id);Event.current.Use();}}
  void CityResourceHeader(){InitCityArt();CityFrame(new Rect(24,18,1552,93));GUI.Label(new Rect(45,31,270,31),"VEILBOUND",CityType(26,cityIvory,true));GUI.Label(new Rect(47,78,268,22),resourceFocus?"LB / RB   A open   B back":CityClock,CityType(11,muted));if(resourceCategory>=0)buttons.Clear();for(int i=0;i<6;i++){int group=i;Rect r=ResourceCategoryRect(i);bool focus=resourceFocus&&resourceFocusCategory==i;var icon=MaterialIcon(ResourceCategoryIcons[i]);if(icon)GUI.DrawTexture(new Rect(r.x+7,r.y+10,41,41),icon);GUI.Label(new Rect(r.x+57,r.y+6,r.width-61,26),ResourceCategories[i],CityType(12,muted));GUI.Label(new Rect(r.x+57,r.y+34,r.width-61,26),Math.Floor(ResourceCategoryStock(i)).ToString("N0"),CityType(18,i==5?new Color(.98f,.25f,.14f):cityIvory,true));int index=buttons.Count;buttons.Add(()=>ToggleResourceCategory(group));if(resourceCategory==i||focus||!resourceFocus&&selection==index)CardOutline(r,cityRed);if(i<4)HudLine(new Vector2(r.xMax+5,r.y+6),new Vector2(r.xMax+5,r.yMax-6),new Color(.20f,.20f,.18f));}HudLine(new Vector2(1290,32),new Vector2(1290,94),citySilver);if(resourceCategory>=0)ResourceDropdown();}
 }
